            and "asset_exif"."city" > "cte"."city"
          order by
            "city"
          limit
            $20
        ) as "l" on true
    )
  )
select
  "asset"."id",
  "asset"."updateId",
  "asset"."createdAt",
  "asset"."updatedAt",
  "asset"."deletedAt",
  "asset"."status",
  "asset"."checksum",
  "asset"."checksumAlgorithm",
  "asset"."duplicateId",
  "asset"."duration",
  "asset"."fileCreatedAt",
  "asset"."fileModifiedAt",
  "asset"."isExternal",
  "asset"."isOffline",
  "asset"."isEdited",
  "asset"."visibility",
  "asset"."libraryId",
  "asset"."livePhotoVideoId",
  "asset"."localDateTime",
  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height",
  to_jsonb("asset_exif") as "exifInfo",
  exists (
    select
      1 as "exists"
    from
      "asset_favorite"
    where
      "asset_favorite"."assetId" = "asset"."id"
      and "asset_favorite"."userId" = $21::uuid
  ) as "isFavoriteForUser"
from
  "asset"
  inner join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
  inner join "cte" on "asset"."id" = "cte"."assetId"
order by
  "asset_exif"."city"

