  "asset"."fileModifiedAt",
  "asset"."isExternal",
  "asset"."isOffline",
  "asset"."isEdited",
  "asset"."visibility",
  "asset"."libraryId",
  "asset"."livePhotoVideoId",
  "asset"."localDateTime",
  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height"
from
  "asset"
  left join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
where
  "asset"."ownerId" = any ($1::uuid[])
  and (
    "asset"."visibility" != $2
    or "asset"."ownerId" = $3
  )
  and (
    exists (
      select
        1 as "exists"
      from
        "asset_favorite"
      where
        "asset_favorite"."assetId" = "asset"."id"
        and "asset_favorite"."userId" = $4::uuid
    )
    or exists (
      select
      from
        "asset_face"
      where
        "asset_face"."assetId" = "asset"."id"
        and "asset_face"."deletedAt" is null
        and "asset_face"."isVisible" = $5
        and "asset_face"."personGroupId" = any ($6::uuid[])
    )
  )
order by
  "asset"."fileCreatedAt" desc,
  "asset"."id" desc
limit
  $7
offset
  $8

-- SearchRepository.searchMetadataV3 (or-with-top-level)
select
  "asset"."id",
  "asset"."updateId",
  "asset"."createdAt",
  "asset"."updatedAt",
  "asset"."deletedAt",
  "asset"."status",
  "asset"."checksum",
  "asset"."checksumAlgorithm",
