  "asset"."originalFileName",
  "asset"."originalPath",
  "asset"."ownerId",
  "asset"."stackId",
  "asset"."thumbhash",
  "asset"."type",
  "asset"."width",
  "asset"."height"
from
  "asset"
  left join "asset_exif" on "asset"."id" = "asset_exif"."assetId"
where
  (
    "asset"."visibility" != $1
    or "asset"."ownerId" = $2
  )
  and (
    "asset"."fileCreatedAt" < $3
    and "asset"."fileCreatedAt" >= $4
    and (
      (
        exists (
          select
            1 as "exists"
          from
            "asset_favorite"
